/bin/bash -lc "python - <<'PY'
import json, os, urllib.request, urllib.parse
base=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f:
    key=f.read().strip()
tool_id='toolshed.g2.bx.psu.edu/repos/devteam/bwa/bwa_mem/0.7.19+galaxy1'
url=base+'/api/tools/'+urllib.parse.quote(tool_id,safe='')+'?io_details=true&link_details=true'
req=urllib.request.Request(url,headers={'x-api-key':key})
with urllib.request.urlopen(req) as resp:
    data=json.load(resp)

def walk(x,path=''):
    if isinstance(x,dict):
        for k,v in x.items(): walk(v,path+'/'+str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+'/'+str(i))
    elif isinstance(x,str) and ('hg38' in x.lower() or 'grch38' in x.lower()):
        print(path,repr(x))
walk(data)
PY"

